var e=class{constructor(e){this.root=e,this.form=e.querySelector(`[data-cart-form]`),this.updateButton=e.querySelector(`[data-cart-update]`),this.submitTimer=null}init(){!this.form||!this.updateButton||(this.form.addEventListener(`click`,e=>this.handleClick(e)),this.form.addEventListener(`change`,e=>this.handleChange(e)))}handleClick(e){let t=e.target.closest(`[data-cart-minus], [data-cart-plus]`);if(!t)return;let n=t.closest(`.cart-quantity`)?.querySelector(`[data-cart-quantity]`);if(!n)return;let r=Number(n.min||1),i=n.max?Number(n.max):1/0,a=t.hasAttribute(`data-cart-plus`)?1:-1;n.value=String(Math.max(r,Math.min(i,Number(n.value||r)+a))),this.scheduleSubmit()}handleChange(e){if(!e.target.matches(`[data-cart-quantity]`))return;let t=e.target,n=Number(t.min||1),r=t.max?Number(t.max):1/0;t.value=String(Math.max(n,Math.min(r,Number(t.value||n)))),this.scheduleSubmit()}scheduleSubmit(){window.clearTimeout(this.submitTimer),this.submitTimer=window.setTimeout(()=>this.updateButton.click(),250)}},t=document.querySelector(`[data-cart-page]`);t&&new e(t).init();